#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> p(n);
    for (int i = 0; i < n; i++) cin >> p[i];

    vector<pair<long long, int>> stack;
    for (int i = 0; i < n; i++) {
        int span = 1;
        while (!stack.empty() && stack.back().first <= p[i]) {
            span += stack.back().second;
            stack.pop_back();
        }
        stack.push_back({p[i], span});
        cout << span << (i + 1 < n ? " " : "\n");
    }

    return 0;
}

