import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] p = new long[(int) n];
        for (int i = 0; i < p.length; i++) p[i] = Long.parseLong(next());

        long[] prices = new long[(int) n];
        int[] spans = new int[(int) n];
        int size = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int span = 1;
            while (size > 0 && prices[size - 1] <= p[i]) {
                size--;
                span += spans[size];
            }
            prices[size] = p[i];
            spans[size] = span;
            size++;
            sb.append(span).append(i + 1 < n ? " " : "\n");
        }
        System.out.print(sb);
    }
}
